module top_module (
	input [4:0] a,
	input [4:0] b,
	input [4:0] c,
	input [4:0] d,
	input [4:0] e,
	input [4:0] f,
	output [7:0] w,
	output [7:0] x,
	output [7:0] y,
	output [7:0] z
);

wire [31:0] concat;

// Concatenate the six 5-bit input vectors and append two 1 bits at the LSB positions.
// Total bits: (6 * 5) + 2 = 32 bits.
assign concat = {a, b, c, d, e, f, 2'b11};

// Split the 32-bit concatenation into four 8-bit output vectors.
assign w = concat[7:0];
assign x = concat[15:8];
assign y = concat[23:16];
assign z = concat[31:24];

endmodule
